//Rajkin Hossain.......
import java.io.*;
import java.util.*;
public class B{




    public static void main(String [] args)throws IOException{
        //FI k = new FI("E:/b.txt");
    	FI k = new FI(System.in);
    	//Scanner k = new Scanner(new File("E:/b.txt"));
    	PrintWriter z = new PrintWriter(System.out);
    	while(k.hasNext()){
    		int n = k.nextInt();
    		String s = k.next();
    		boolean ok = false;
    		int one = 0;
    		String tt = "";
    		String twoans = "";
    		boolean wordnok = true;
    		for(int c = 0;c<n;c++){
    			char ch = s.charAt(c);
    			if(ch == '('){
    				ok = true;
    				wordnok = true;
    				tt = "";
    			}
    			else if(ch == ')'){
    				tt = "";
    				ok = false;
    			}
    			else{
    				if(ok == false){

    					if(ch == '_'){
    						tt = "";
    					}
    					else{
    						tt += ch;
    					}

    					if(tt.length()>twoans.length()){
							twoans = tt;
						}
    				}
    				else{
    					if(ch == '_'){
    						wordnok = true;
    					}
    					else{
    						if(wordnok){
    							one++;
    							wordnok = false;
    						}
    					}
    				}
    			}


    		}
    		z.println(twoans.length()+" "+one);
    	}


       	z.flush();

    }


	public static class FI {
	    BufferedReader br;
	    StringTokenizer st;

	    public FI(InputStream stream){
	        br = new BufferedReader(new InputStreamReader(stream));
	    }

	    public FI(String s){
	        try {
				br = new BufferedReader(new FileReader(s));
			} catch (FileNotFoundException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
			}
	    }

	    public String next() {
	        return nextToken();
	    }


	    public boolean hasNext(){
	    	try {
				return br.ready();
			} catch (IOException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
			}
			return false;
	    }

	    public String nextToken() {
	        while (st == null || !st.hasMoreTokens()) {
	            String line = null;
	            try {
	                line = br.readLine();
	            } catch (IOException e) {
	                throw new RuntimeException(e);
	            }
	            if (line == null) {
	                return null;
	            }
	            st = new StringTokenizer(line);
	        }
	        return st.nextToken();
	    }

	    public int nextInt() {
	        return Integer.parseInt(nextToken());
	    }

	    public long nextLong() {
	        return Long.valueOf(nextToken());
	    }

	}




    public static class FO extends PrintWriter {
        FO() { super(new BufferedOutputStream(System.out)); }
    }

}

